  "question": "Cho $a$, $b$ là hai số thực dương khác $1$ thỏa mãn đồ thị hàm số $y=f(x)=\\log_a x+\\log_b x$ luôn đi qua điểm $M(\\mathrm{e};20)$. Tính đạo hàm của hàm số tại điểm $x=5$.",
