  "question": "Cho hàm số $f(x)=\\left\\{\\begin{array}{ll}x^2-6x+2 & \\text{khi} x &gt; 2\\\\3a+1 & \\text{khi} x \\le 2\\end{array}\\right.$, với $a$ là số thực. Xét tính đúng sai các phát biểu sau",
