  "explain": "<br><img src=\"data/11/1D5/im1D51/dlts_11_DLTS17_005.png\" alt=\"hinh ve\" style=\"max-width:min(560px,90%);max-height:300px;width:auto;height:auto;display:block;margin:8px auto;\">  <br>- Cỡ mẫu $n=10+14+31+2+5+23=85$.<br>  Ta có $\\overline{x}=\\dfrac{10\\cdot 3+14\\cdot 7+31\\cdot 11+2\\cdot 15+5\\cdot 19+23\\cdot 23}{85}=\\dfrac{1\\,123}{85}\\approx 13{,}21$ giờ.<br>  Do đó “ Thời gian mượn sách đọc tại thư viện trung bình của sinh viên trong mẫu số liệu ghép nhóm trên là $13{,}21$ giờ.”.<br>- Cỡ mẫu $n=10+14+31+2+5+23=85$.<br>- Độ dài của mỗi nhóm bằng $5-1=4$.<br>- Nhóm có số lượng sinh viên nhiều nhất là $[9; 13)$ với $31$ sinh viên.<br>  Ta có $M_o=9+\\dfrac{31-14}{(31-14)+(31-2)}\\cdot 4\\approx10{,}48$ giờ.<br>  Thời gian sinh viên mượn sách đọc tại thư viện trong mẫu số liệu ghép nhóm trên nhiều nhất là $10{,}48$ giờ.",
