  "question": "Cho $(C)$ là đồ thị của hàm số $f(x)=\\dfrac{2}{x}+2025$ và điểm $M(1;2027)\\in(C)$. Tính hệ số góc của tiếp tuyến của $(C)$ tại điểm $M$.",
  "answer": "-2",
  "explain": "Ta có $f'(x)=\\left(\\dfrac{2}{x}+2025\\right)'=\\left(\\dfrac{2}{x}\\right)'+2025'=-\\dfrac{2}{x^2}$.<br>  Hệ số góc của tiếp tuyến của $(C)$ tại điểm $M(1;2027)\\in(C)$ là $f'(1)=-2$.",
